// TH18 v1.00a st03bs.ecl.txt BossCard3 (s:784-945).
// Target card t0 = source card start; a 120-frame practice buffer precedes it.
// Control enemy at (0,0) owns the spell and has no body collision; the real
// boss at (0,128) keeps the source hurtbox/body box.
const TIME_LIMIT: int = 2820;      // 120 opening buffer + 2700 source timeout
const SOURCE_LIMIT: int = 2700;    // s:811 setInterrupt(0,0,2700,"BossDead")
const OPENING_BUFFER: int = 120;
const TH18_BIG_BALL2: int = 656;   // s:887 etSprite(0,19,1), type 19 color 1
const TH18_SHARD: int = 512;       // s:908 SHOOT_DATA sprite 10 color 4
const ANGLE_STEP: int = 6554;      // s:831-832 / s:865 B=0.628319 rad per shot

// s:891 etExSet(0,0,type2 a=1): birth ANIM; the 4*velocity retreat is kept
// through sh_dist below. s:893 VELTIME a=120 r=0 s=-1000000: 1.5 -> 0.
// s:908 SHOOT_DATA c=1 deletes the parent once the ring is out.
xformdef PARENT_DECEL(life_frames: int) {
    set_accel(at_spawn((0fx - $self_speed) / 120fx));
    wait(life_frames);
    set_life(1);
}

// s:931 etExSet(0,15,type2097152 a=140 r=0.6 s=-1000000): per-layer
// initial speed 3/2/1 decays to 0.6 over 140 frames.
xformdef CHILD_DECEL {
    set_accel(at_spawn((0.6fx - $self_speed) / 140fx));
    wait(140);
    stop_fx();
}

// s:902-925 parent bullet EX records 3-8, rebuilt as a bullet task because
// the line lasers are separate entities. Records 3+4 fire one line every 10
// frames; record 5 WAIT10; record 6 GOTO index3 with count 1/3. Record 7 then
// emits the 28-way ring and record 8 removes the parent.
async sub parent_lasers() {
    var rank: int = global(GVAR_RANK);
    var lasers: int = 1;
    var speed: fx = 3fx;
    if rank >= 1 {
        lasers = 3;
        speed = 4fx;
    }
    for i in 0..lasers {
        // s:903 line LASER a=0 b=20 c=1; r=1000000 => current bullet-to-player
        // angle (TH18 [999990,1999990)); s = 3/4 px/frame; paired record s2=16
        // width => half-height 4 => target full width 8. Record m=0/n=128 is
        // initial/target line length; the source collision segment is the
        // default Line 0.1L..0.9L, represented by lz_start 12.8 and rod 102.4.
        var h: int = laser(1, $self_x, $self_y, aim_player(), 12.8fx, 8fx, 0, 240, 0);
        lz_speed(h, speed, 102.4fx);
        wait(10);                              // s:905 WAIT 10
    }
    // s:903 etExSet2(0,7,type8192) SHOOT: mode3 fixed ring, 28 ways,
    // layers 1/3, alpha=delta=0, speeds 3->1. s:908 paired SHOOT_DATA uses
    // type10 shard color 4 and deletes the parent.
    var layers: int = 1;
    if rank >= 1 { layers = 3; }
    sh_reset(0);
    sh_sprite(0, TH18_SHARD, 4);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 28, 1);
    sh_angle(0, 0deg, 0deg);
    var v: fx = 3fx;
    for q in 0..layers {
        var back: fx = 0fx - 4fx * v;          // s:915 ANIM a=1 retreat
        sh_speed(0, v, 0fx);
        sh_dist(0, back);
        sh_xform(0, CHILD_DECEL);
        sh_fire(0);
        v = v - 1fx;
    }
}

// s:884-930: one parent shot, etAim(0,1) fixed direction, 1.5 px/frame,
// N=1 so etAngle's fan delta is unused. s:891 ANIM retreat = -4*1.5 = -6.
sub fire_parent(a: angle, lasers: int) {
    var life: int = 10 * lasers + 1;           // task runs one frame after spawn
    sh_reset(1);
    sh_sprite(1, TH18_BIG_BALL2, 1);
    sh_aim(1, 0);
    sh_ring(1, 0);
    sh_count(1, 1, 1);
    sh_angle(1, a, 0deg);
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, -6fx);
    sh_xform(1, PARENT_DECEL(life));
    sh_task(1, parent_lasers);
    sh_fire(1);
}

// s:412 moveRand(120,4,1.0) with s:820 moveLimit(0,128,200,48).
// Actual bounds x[-100,100], y[104,152]; source inner direction box
// x[-50,50], y[116,140]. Speed is the source speed slot's linear 1 -> 0.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 120 { speed = (120 - k) as fx / 120fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -100fx { nx = -100fx; }
    if nx > 100fx { nx = 100fx; }
    if ny < 104fx { ny = 104fx; }
    if ny > 152fx { ny = 152fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -50fx {
        a = r / 3;
    } else if $self_x > 50fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 116fx {
        if a < 0 { a = -a; }
    } else if $self_y > 140fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                          // s:500 setHurtbox(40,40) / 2
    set_hitbox(24fx);                           // s:501 setHitbox(48,48) / 2
    set_self_int(2, 60);                        // s:831 $I0
    set_self_int(3, 1);                         // s:832 $I1
    wait(OPENING_BUFFER);                       // source card t0 (s:784)
    set_self_int(1, $frame + SOURCE_LIMIT);
    wait(OPENING_BUFFER);                       // s:823-833 +60/+120 labels; first call s:844 at source t120
    var rank: int = global(GVAR_RANK);
    var shots: int = 6;                         // s:934 diffI C
    if rank == 2 { shots = 9; }
    if rank == 3 { shots = 11; }
    var lasers: int = 1;
    if rank >= 1 { lasers = 3; }
    var a: angle = 0deg;                        // s:844 first call A=0
    var b: angle = ANGLE_STEP as angle;         // s:836 +0.628319
    loop {
        if $frame >= self_int(1) { return; }
        var step: angle = a;
        for j in 0..shots {
            if $frame >= self_int(1) { return; }
            fire_parent(step, lasers);
            step = step + b;                    // s:940 A += B
            for i in 0..30 {                    // s:939 wait(30)
                wait(1);
                if $frame >= self_int(1) { return; }
            }
        }
        if $frame >= self_int(1) { return; }
        card_move_rand();                       // s:845/866 moveRand(120,4,1.0)
        for iw in 0..160 {                      // s:855/876 wait(160)
            wait(1);
            if $frame >= self_int(1) { return; }
            card_arm_next_step();
        }
        a = 32768 as angle - a;                 // s:865 second call A=pi
        b = 0deg - b;                           // s:862 -0.628319
    }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // s:811 source timeout 2700, s:813 spell(28,2700,...).
    spell_begin(0, 28, none, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    _ = spawn_enemy(0fx, 128fx, 19800, 0, 0, 0, boss_main);
    loop { wait(600); }
}
